#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO 2
#define GPIO_ALT 3

static int setup_gpio(int gpio) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    ret = gpiod_chip_open(&chip, "gpiochip0");
    if (ret < 0) {
        perror("Failed to open gpiochip");
        return ret;
    }

    ret = gpiod_chip_get_line(chip, gpio, 0, &line);
    if (ret < 0) {
        gpiod_chip_put(chip);
        perror("Failed to get line");
        return ret;
    }

    ret = gpiod_line_export(line, NULL);
    if (ret < 0) {
        gpiod_line_release(line);
        gpiod_chip_put(chip);
        perror("Failed to export line");
        return ret;
    }

    ret = gpiod_line_request_set_dir(line, GPIO_ALT);
    if (ret < 0) {
        gpiod_line_release(line);
        gpiod_chip_put(chip);
        perror("Failed to set direction");
        return ret;
    }

    return 0;
}

static void cleanup_gpio(int gpio) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    ret = gpiod_chip_open(&chip, "gpiochip0");
    if (ret < 0) {
        perror("Failed to open gpiochip");
        return;
    }

    ret = gpiod_chip_get_line(chip, gpio, 0, &line);
    if (ret < 0) {
        gpiod_chip_put(chip);
        perror("Failed to get line");
        return;
    }

    gpiod_line_release(line);
    gpiod_chip_put(chip);
}

int main(void) {
    int gpio = GPIO;
    int ret;

    if (setup_gpio(gpio) < 0) {
        return 1;
    }

    while (1) {
        ret = gpiod_line_trigger(gpio, GPIO_FALLING_EDGE);
        if (ret < 0) {
            fprintf(stderr, "Failed to trigger line: %s\n", gpiod_strerror(ret));
            cleanup_gpio(gpio);
            return 1;
        }

        printf("Setting GPIO %d to LOW\n", gpio);
        usleep(1000000);

        ret = gpiod_line_trigger(gpio, GPIO_FALLING_EDGE);
        if (ret < 0) {
            fprintf(stderr, "Failed to trigger line: %s\n", gpiod_strerror(ret));
            cleanup_gpio(gpio);
            return 1;
        }

        printf("Setting GPIO %d to HIGH\n", gpio);
        usleep(1000000);
    }

    cleanup_gpio(gpio);
    return 0;
}

