int main(int argc, char *argv[])
{
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    chip = gpiod_chip_open_r("/dev/gpiod", O_RDWR);
    if (!chip) {
        fprintf(stderr, "Failed to open gpiod device\n");
        return 1;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Device %d not found\n", GPIO_PIN);
