    }

    if (gpiod_line_request_cooked(line, 1)) {
        fprintf(stderr, "Failed to request line\n");
        gpiod_chip_close(chip);
        return 1;
    }

    while (1) {
        ret = gpiod_line_get_value(line);
        if (ret < 0) {
            fprintf(stderr, "Failed to read line value\n");
            break;
        }

        printf("Current state: %s\n", (ret == 1) ? "HIGH" : "LOW");

        sleep(CHECK_INTERVAL);
    }

    gpiod_line_drain_sink(line);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <gpiod.h>

#define ADS1115_I2C_ADDR 0x48
#define ADS1115_REG_CONFIG 0x00
#define ADS1115_REG_RESULT_LOW 0x01
#define ADS1115_REG_RESULT_HIGH 0x02
#define ADS1115_GAIN_ONE 0x00
#define ADS1115_GAIN_TWO 0x01
#define ADS1115_GAIN_FOUR 0x02
#define ADS1115_GAIN_EIGHT 0x03

int ads_read(int fd, int channel, int gain) {
    uint8_t config[2];
    uint16_t result;

    // Configure ADS1115
    config[0] = (ADS1115_REG_CONFIG | (channel & 0x0F) | ((gain == ADS1115_GAIN_ONE) ? 0x00 : ((gain == ADS1115_GAIN_TWO) ? 0x20 : ((gain == ADS1115_GAIN_FOUR) ? 0x40 : 0x60))));
    write(fd, config, 2);

    // Read result
    readn(fd, &result, 2);

    return (result >> 4) & 0x0FFF;
}

int main() {
    int fd, res;
    struct i2c_rdwr_ioctl_data rdwr;
    struct gpiod_chip chip;
    struct gpiod_line line;
    int ret;

    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Failed to open i2c bus");
        return 1;
    }

    ioctl(fd, I2C_SLAVE, ADS1115_I2C_ADDR);

    rdwr.u8 = ADS1115_REG_RESULT_LOW;
    rdwr.u16 = 0;
    rdwr.u32 = 0;
    rdwr.u64 = 0;
    rdwr.len = 1;
    rdwr.buf = &res;

    ret = ioctl(fd, I2C_RDWR, &rdwr);
    if (ret < 0) {
        perror("Failed to read from ADS1115");
        close(fd);
        return 1;
    }

    // Initialize GPIO for interrupt
    ret = gpiod_chip_open(&chip, "gpiochip0");
    if (ret < 0) {
        perror("Failed to open gpiochip");
        close(fd);
        return 1;
    }

    ret = gpiod_chip_get_line(&chip, "gpio0", &line);
    if (ret < 0) {
        perror("Failed to get gpio line");
        gpiod_chip_close(&chip);
        close(fd);
        return 1;
    }

    gpiod_line_set_dir(&line, GPIO_DIR_OUT);

    // Start sampling
    while (1) {
        uint16_t adc_value = ads_read(fd, 0, ADS1115_GAIN_ONE);
        printf("ADC Value: %d\n", adc_value);

        // Simulate interrupt
        gpiod_line_trigger(&line, 1);
        usleep(500000); // 0.5 seconds delay
    }

    // Release resources
    gpiod_line_release(&line);
    gpiod_chip_close(&chip);
    close(fd);

    return 0;
}

