    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open i2c bus\n");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MLX90614_ADDR) < 0) {
        fprintf(stderr, "Failed to acquire i2c bus\n");
        close(i2c_fd);
        return 1;
    }

    rdwr_data.u8 = REG_THERM1;
    rdwr_data.u16 = &rdwr_data.u32;
    ret = ioctl(i2c_fd, I2C_RDWR, &rdwr_data);
    if (ret < 0) {
        fprintf(stderr, "Failed to read from MLX90614\n");
        close(i2c_fd);
        return 1;
    }

    uint16_t temp1 = rdwr_data.u32;

    rdwr_data.u8 = REG_THERM2;
    ret = ioctl(i2c_fd, I2C_RDWR, &rdwr_data);
    if (ret < 0) {
        fprintf(stderr, "Failed to read from MLX90614\n");
        close(i2c_fd);
        return 1;
    }

    uint16_t temp2 = rdwr_data.u32;

    printf("Temperature (°C): %d.%02d\n", temp1 / 16, (temp1 % 16) / 2);
    printf("Object Temperature (°C): %d.%02d\n", temp2 / 16, (temp2 % 16) / 2);

    while (1) {
        sleep(5);

        rdwr_data.u8 = REG_THERM1;
        ret = ioctl(i2c_fd, I2C_RDWR, &rdwr_data);
        if (ret < 0) {
            fprintf(stderr, "Failed to read from MLX90614\n");
            close(i2c_fd);
            return 1;
        }

        temp1 = rdwr_data.u32;

        rdwr_data.u8 = REG_THERM2;
        ret = ioctl(i2c_fd, I2C_RDWR, &rdwr_data);
        if (ret < 0) {
            fprintf(stderr, "Failed to read from MLX90614\n");
            close(i2c_fd);
            return 1;
        }

        temp2 = rdwr_data.u32;

        printf("Temperature (°C): %d.%02d\n", temp1 / 16, (temp1 % 16) / 2);
        printf("Object Temperature (°C): %d.%02d\n", temp2 / 16, (temp2 % 16) / 2);
    }

    close(i2c_fd);
    return 0;
}

