#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <gpiod.h>

#define ADS1115_I2C_ADDR 0x48
#define ADS1115_REG_CONFIG 0x00
#define ADS1115_REG_RESULT_LOW 0x01
#define ADS1115_REG_RESULT_HIGH 0x02
#define ADS1115_GAIN_ONE 0x00
#define ADS1115_GAIN_TWO 0x01
#define ADS1115_GAIN_FOUR 0x02
#define ADS1115_GAIN_EIGHT 0x03

int ads_read(int fd, int channel, int gain) {
    uint8_t config[2];
    uint16_t result;

    // Configure ADS1115
    config[0] = (ADS1115_REG_CONFIG | channel | (gain << 6));
    write(fd, config, 2);

    // Read low and high bytes from ADS1115
    read(fd, &config[0], 1);
    read(fd, &config[1], 1);

    // Combine low and high bytes into 16-bit result
    result = ((uint16_t)config[1] << 8) | config[0];

    return result;
}

int main() {
    int fd, res;
    int channel = 0; // Single-ended input on pin A0
    int gain = ADS1115_GAIN_ONE; // 1x gain

    // Open I2C device
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Failed to open i2c bus");
        return 1;
    }

    // Set I2C address
    if (ioctl(fd, I2C_SLAVE, ADS1115_I2C_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(fd);
        return 1;
    }

    // Configure ADS1115 for single-ended mode and specified gain
    res = ads_read(fd, channel, gain);
    if (res < 0) {
        fprintf(stderr, "Failed to read from ADS1115\n");
        close(fd);
        return 1;
    }

    printf("ADC reading: %d\n", res);

    // Main loop
    while (1) {
        sleep(0.1);
        res = ads_read(fd, channel, gain);
        if (res < 0) {
            fprintf(stderr, "Failed to read from ADS1115\n");
            break;
        }
        printf("ADC reading: %d\n", res);
    }

    // Close I2C device
    close(fd);

    return 0;
}

