int main(void) {
    int ret;

    // Initialise pigpio library
    if ((ret = gpioInitialise()) < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", gpioErrorString(ret));
        return 1;
    }

    // Check if the GPIO pin is available
    if (gpioGetMode(GPIO_PIN) == GPIO_OUTPUT) {
        gpioSetMode(GPIO_PIN, PI_OUTPUT);
    } else {
        fprintf(stderr, "GPIO %d is not available\n", GPIO_PIN);
        gpioTerminate();
        return 1;
    }

    // Set PWM parameters
    gpioSetPWMfrequency(GPIO_PIN, PERIOD_US);
    gpioSetPWMrange(GPIO_PIN, 100);

    while (1) {
        // Set PWM duty cycle (50% in this case)
        gpioPWM(GPIO_PIN, 512); // 50% duty cycle
        printf("PWM state: %d\n", gpioGetPWMoutput(GPIO_PIN));
        usleep(PERIOD_US);
    }

    // Clean up
    gpioTerminate();
    return 0;
}

