#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <gpiod.h>

#define TRIG_GPIO 17
#define ECHO_GPIO 27
#define MEASURE_INTERVAL 60

int main() {
    struct gpiod_chip chip;
    struct gpiod_line line_trig;
    struct gpiod_line line_echo;
    struct gpiod_context *ctx;
    int ret;

    ctx = gpiod_new();
    if (!ctx) {
        fprintf(stderr, "Failed to create gpiod context\n");
        return 1;
    }

    ret = gpiod_chip_open(ctx, "gpiochip0", &chip);
    if (ret) {
        fprintf(stderr, "Failed to open gpiochip0\n");
        gpiod_free(ctx);
        return 1;
    }

    line_trig = gpiod_chip_get_line(chip, "gpio17");
    line_echo = gpiod_chip_get_line(chip, "gpio27");

    if (!line_trig || !line_echo) {
        fprintf(stderr, "Failed to get line for HC-SR04\n");
        gpiod_chip_close(chip);
        gpiod_free(ctx);
        return 1;
    }

    if (gpiod_line_request_cooked_output(line_trig, 1) || gpiod_line_request_cooked_output(line_echo, 1)) {
        fprintf(stderr, "Failed to request output for trigger line\n");
        gpiod_line_release(line_trig);
        gpiod_line_release(line_echo);
        gpiod_chip_close(chip);
        gpiod_free(ctx);
        return 1;
    }

    if (gpiod_line_request_cooked_input(line_echo, 1)) {
        fprintf(stderr, "Failed to request input for echo line\n");
        gpiod_line_release(line_trig);
        gpiod_line_release(line_echo);
        gpiod_chip_close(chip);
        gpiod_free(ctx);
        return 1;
    }

    while (1) {
        gpiod_line_trigger(line_trig, true);
        usleep(10);
        gpiod_line_trigger(line_trig, false);

        uint64_t elapsed_us = gpiod_line_get_value_us(line_echo, 1);
        if (elapsed_us == 0) {
            fprintf(stderr, "HC-SR04 did not respond\n");
            break;
        }

        double distance_cm = elapsed_us / 29.0;
        printf("Distance: %.2f cm\n", distance_cm);

        sleep(MEASURE_INTERVAL);
    }

    gpiod_line_release(line_trig);
    gpiod_line_release(line_echo);
    gpiod_chip_close(chip);
    gpiod_free(ctx);

    return 0;
}

#include <stdio.h>
