#define ADS1115_REG_RESULT_LOW 0x01
#define ADS1115_REG_RESULT_HIGH 0x02
#define ADS1115_GAIN_ONE 0x00
#define ADS1115_GAIN_TWO 0x01
#define ADS1115_GAIN_FOUR 0x02
#define ADS1115_GAIN_EIGHT 0x03

int ads_init(int fd) {
    if (ioctl(fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        return -1;
    }

    struct gpiod_chip chip;
    gpiod_chip_init(&chip, "ads1115");
    chip.pin_usage = "ads1115";
    chip.num_pins = 2;

    struct gpiod_chip_usage usage[] = {
        {
            .which = 0,
            .flags = GPIOD_INPUT,
            .debounce_timeout_ns = 0,
        },
        {
            .which = 1,
            .flags = GPIOD_OUTPUT,
            .debounce_timeout_ns = 0,
        },
    };
    chip.usage = usage;
    chip.num_usages = sizeof(usage) / sizeof(usage[0]);

    int ret = gpiod_chip_add_usage(&chip, "ads1115-config", usage[0]);
    if (ret < 0) {
        fprintf(stderr, "Failed to add chip usage: %d\n", ret);
        return ret;
    }

    ret = gpiod_chip_add_usage(&chip, "ads1115-data", usage[1]);
    if (ret < 0) {
        fprintf(stderr, "Failed to add chip usage: %d\n", ret);
        return ret;
    }

    ret = gpiod_chip_register(&chip);
    if (ret < 0) {
        fprintf(stderr, "Failed to register chip: %d\n", ret);
        return ret;
    }

    return 0;
}

