    config.mds_bit = 0;
    config.cpol_bit = 0;
    config.clrc_bit = 0;
    config.diff_bit = 0;
    config.sha_bit = 0;
    config.pds_bit = 0;
    config.os_bit = 0;
    config.wg_bit = 0;
    config.intrc_bit = 0;
    config.lowres_bit = 0;
    config.simc_bit = 0;
    config.comp_bit = 0;
    config.comp_latch_bit = 0;
    config.comp_result_bit = 0;
    config.comp_window_bit = 0;
