#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONFIG 0x00
#define ADS1115_REG_LOW_THS 0x01
#define ADS1115_REG_HIGH_THS 0x02
#define ADS1115_REG_DATAX0 0x03

#define CHANNEL_AIN0 0

int main(int argc, char *argv[])
{
    int file;
    char *dev_name = "/dev/i2c-1";
    gpio_init();

    if ((file = open(dev_name, O_RDWR)) < 0) {
        perror("Failed to open i2c bus");
        return 1;
    }

    if (ioctl(file, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        return 1;
    }

    // Configure the ADS1115 to use the internal reference and gain of 1
    uint8_t config = (ADS1115_REG_CONFIG |
                      (1 << 5) | // PLL gain
                      (1 << 4) | // Right-aligned
                      (1 << 3) | // Single-shot mode
                      (CHANNEL_AIN0 << 1) | // AIN0 channel
                      (1 << 0)); // Enable the device

    if (write(file, &config, 1) != 1) {
        perror("Failed to write to ADS1115 register");
        return 1;
    }

    // Set the low and high threshold registers to the full-scale range
    uint8_t low_thresh = 0;
    uint8_t high_thresh = 0xFF;

    if (write(file, &low_thresh, 1) != 1) {
        perror("Failed to write low threshold register");
        return 1;
    }

    if (write(file, &high_thresh, 1) != 1) {
        perror("Failed to write high threshold register");
        return 1;
    }

    // Read the data from the AIN0 channel
    uint16_t data;
    if (read(file, &data, 2) != 2) {
        perror("Failed to read from ADS1115 register");
        return 1;
    }

    printf("ADC reading: %d\n", data);

    close(file);
    gpio_cleanup();

    return 0;
}

