#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <gpiod_bcm.h>

#define GPIO_17 17
#define GPIO_18 18
#define INTERVAL_SEC 0.1

static int setup_gpio(int gpio) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    chip = gpiod_chip_open_r(NULL);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return -1;
    }

    line = gpiod_chip_get_line(chip, gpio);
    if (!line) {
        fprintf(stderr, "Failed to get line for GPIO %d\n", gpio);
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_export(line, NULL);
    if (ret < 0) {
        fprintf(stderr, "Failed to export GPIO %d\n", gpio);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

static void cleanup_gpio(int gpio) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;

    chip = gpiod_chip_open_r(NULL);
    line = gpiod_chip_get_line(chip, gpio);

    if (line) {
        gpiod_line_release(line);
    }

    gpiod_chip_close(chip);
}

static int toggle_gpio(int gpio) {
    struct gpiod_line *line;
    int ret;

    line = gpiod_chip_get_line(gpiod_chip_open_r(NULL), gpio);
    if (!line) {
        fprintf(stderr, "Failed to get line for GPIO %d\n", gpio);
        return -1;
    }

    ret = gpiod_line_direction_input(line);
    if (ret < 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", gpio);
        gpiod_line_release(line);
        return -1;
    }

    ret = gpiod_line_direction_output(line);
    if (ret < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", gpio);
        gpiod_line_release(line);
        return -1;
    }

    ret = gpiod_line_set_value(line, 1);
    if (ret < 0) {
        fprintf(stderr, "Failed to set GPIO %d high\n", gpio);
        gpiod_line_release(line);
        return -1;
    }

    usleep(100000); // Wait for 0.1 seconds
    ret = gpiod_line_set_value(line, 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to set GPIO %d low\n", gpio);
        gpiod_line_release(line);
        return -1;
    }

    gpiod_line_release(line);
    return 0;
}

int main(int argc, char *argv[]) {
    int ret;
    int gpio;

    if (argc != 1) {
        fprintf(stderr, "Usage: %s\n", argv[0]);
        return 1;
    }

    for (gpio = GPIO_17; gpio <= GPIO_18; ++gpio) {
        ret = setup_gpio(gpio);
        if (ret < 0) {
            return ret;
        }
    }

    while (1) {
        for (gpio = GPIO_17; gpio <= GPIO_18; ++gpio) {
            ret = toggle_gpio(gpio);
            if (ret < 0) {
                fprintf(stderr, "Error toggling GPIO %d, exiting\n", gpio);
                goto cleanup;
            }
            printf("Toggled GPIO %d\n", gpio);
        }
        usleep(INTERVAL_SEC * 1000000);
    }

cleanup:
    for (gpio = GPIO_17; gpio <= GPIO_18; ++gpio) {
        cleanup_gpio(gpio);
    }

    return ret;
}

