#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONFIG (0x00)
#define ADS1115_REG_RESULT_X0 (0x01)
#define ADS1115_REG_RESULT_X1 (0x02)
#define ADS1115_REG_RESULT_Y0 (0x03)
#define ADS1115_REG_RESULT_Y1 (0x04)
#define ADS1115_REG_RESULT_Z0 (0x05)
#define ADS1115_REG_RESULT_Z1 (0x06)

#define CHANNEL_AIN0 (0)
#define CHANNEL_AIN1 (1)
#define CHANNEL_AIN2 (2)
#define CHANNEL_AIN3 (3)

int main() {
    int file;
    char *dev_name = "/dev/i2c-1";
    gpiod_chip_reg_spec chip_spec[] = {
        gpiod_chip_reg_spec_single(0, "ADS1115_CONFIG"),
        gpiod_chip_reg_spec_single(1, "ADS1115_SAMPLE")
    };
    gpiod_chip chip = gpiod_chip_create_from_spec(dev_name, chip_spec, 2);
    if (!chip) {
        fprintf(stderr, "Failed to create GPIO chip\n");
        return 1;
    }

    file = open(dev_name, O_RDWR);
    if (file < 0) {
        fprintf(stderr, "Failed to open i2c bus\n");
        gpiod_chip_free(chip);
        return 1;
    }

    if (ioctl(file, I2C_SLAVE, ADS1115_ADDR) < 0) {
        fprintf(stderr, "Failed to acquire i2c bus\n");
        close(file);
        gpiod_chip_free(chip);
        return 1;
    }

    // Configure ADS1115 for single-shot mode on AIN0
    uint8_t config = (ADS1115_REG_CONFIG |
                       (CHANNEL_AIN0 << 6) | // Select AIN0
                       0x0 << 4 | // MSB_LSB = 12-bit
                       0x10); // Power-on
    write(file, &config, 2);

    // Wait for conversion to complete
    usleep(1);

    uint16_t readings[3];
    for (int i = 0; i < 3; i++) {
        // Start conversion
        gpiod_trigger_output_event(chip, 1);

        // Wait for conversion to complete
        usleep(1000000);

        // Read result
        read(file, &config, 1);
        readings[i] = (config & 0x00FF);

        // Clear end-of-conversion flag
        write(file, &config, 1);
    }

    // Release resources
    close(file);
    gpiod_chip_free(chip);

    // Print readings
    for (int i = 0; i < 3; i++) {
        printf("Reading %d: %d\n", i + 1, readings[i]);
    }

    return 0;
}

