{
    int i;
    double next_report = 1.0;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library.\n");
        return 1;
    }

    for (i = 0; i < num_pins; i++) {
        const int pin = GPIO_PINS[i];

        if (gpioSetMode(pin, PI_OUTPUT) < 0) {
            fprintf(stderr, "Failed to set mode for GPIO %d.\n", pin);
            gpioTermination();
            return 1;
        }

        if (gpioSetPWMfrequency(pin, PWM_FREQ) < 0) {
