            gpioSetPWMfrequency(pin, PWM_FREQ);
            gpioSetMode(pin, PI_OUTPUT);
            gpioTermination();
            return 1;
        }

        gpioPWM(pin, 128); // Set initial duty cycle to 50%

        printf("Initial state for GPIO %d: duty cycle = 128\n", pin);
        next_report -= REPORT_INTERVAL;
    }

    while (1) {
        for (i = 0; i < num_pins; i++) {
