#include <fcntl.h>
#include <termios.h>
#include <errno.h>

#define DEVICE_PATH "/dev/ttyAMA0"

int setup_serial(int *serial_fd) {
    *serial_fd = open(DEVICE_PATH, O_RDWR | O_NOCTTY | O_NDELAY);
    if (*serial_fd == -1) {
        perror("Failed to open serial port");
        return -1;
    }

    struct termios options;
    tcgetattr(*serial_fd, &options);

    cfsetispeed(&options, B9600);
    cfsetospeed(&options, B9600);

    options.c_cflag |= (CLOCAL | CREAD);
    options.c_cflag &= ~PARENB;
    options.c_cflag &= ~CSTOPB;
    options.c_cflag &= ~CSIZE;
    options.c_cflag |= CS8;

    tcflush(*serial_fd, TCIFLUSH);
    tcsetattr(*serial_fd, TCSANOW, &options);

    return 0;
}

void read_serial(int serial_fd) {
    char buffer[256];
    int bytes_read = read(serial_fd, buffer, sizeof(buffer));

    if (bytes_read > 0) {
        printf("Received: %.*s\n", (int)bytes_read, buffer);
    } else if (bytes_read == -1 && errno != EAGAIN) {
        fprintf(stderr, "Error reading from serial port: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
}

int main(void) {
    int serial_fd;
    if (setup_serial(&serial_fd) != 0) {
        return EXIT_FAILURE;
    }

    while (1) {
        read_serial(serial_fd);
        usleep(100000); // Small delay to avoid busy-waiting
    }

    close(serial_fd);
    return EXIT_SUCCESS;
}

