        gpiod_chip_remove_line(chip, GPIO_OUTPUT);
        gpiod_chip_close(chip);
        return r;
    }

    r = gpiod_chip_add_line(chip, GPIO_OUTPUT_ALT, GPIOD_LINE_OUTPUT);
    if (r < 0) {
