        fprintf(stderr, "Failed to setup line %d\n", GPIO_OUTPUT_ALT);
        gpiod_chip_remove_line(chip, GPIO_OUTPUT_ALT);
        gpiod_chip_close(chip);
        return r;
    }

    while (1) {
        r = gpiod_chip_trigger(chip, GPIO_OUTPUT, 1);
        if (r < 0) {
            fprintf(stderr, "Failed to trigger line %d\n", GPIO_OUTPUT);
            break;
        }

        usleep(INTERVAL_US);

        r = gpiod_chip_trigger(chip, GPIO_OUTPUT, 0);
        if (r < 0) {
            fprintf(stderr, "Failed to trigger line %d\n", GPIO_OUTPUT);
            break;
        }

