#define ADXL345_ADDR 0x53
#define REG_DATAX0 0x32
#define REG_DATAX1 0x33
#define REG_DATAY0 0x34
#define REG_DATAY1 0x35
#define REG_DATAZ0 0x36
#define REG_DATAZ1 0x37

int i2c_fd;

int read_adxl345_register(int file_descriptor, unsigned char reg_addr, unsigned short *data) {
    struct i2c_rdwr_ioctl_data rdwr;
    rdwr.ios = 0;
    rdwr.addr = ADXL345_ADDR;
    rdwr.len = 2;
    rdwr.buf = (unsigned char *)data;

    if (ioctl(file_descriptor, I2C_RDWR, &rdwr) < 0) {
        perror("Failed to read from ADXL345 register");
        return -1;
    }

    return 0;
}

int main(int argc, char *argv[]) {
    int ret;
    struct gpiod_chip chip;
    struct gpiod_line line;

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADXL345_ADDR) < 0) {
        fprintf(stderr, "Failed to acquire bus access for ADXL345\n");
        close(i2c_fd);
        return 1;
    }

    ret = gpiod_chip_register_device(&chip, "ADXL345_INT", 0);
    if (ret) {
        fprintf(stderr, "Failed to register GPIO device\n");
        close(i2c_fd);
        return 1;
    }

    ret = gpiod_chip_get_line(&chip, "ADXL345_INT", &line, 0);
    if (ret) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_unregister(&chip);
        close(i2c_fd);
        return 1;
    }

    gpiod_add_callback(&line, GPIOD_CB_LED_CHANGE, NULL, NULL);

    unsigned short data[6];
    while (1) {
        read_adxl345_register(i2c_fd, REG_DATAX0, &data[0]);
        read_adxl345_register(i2c_fd, REG_DATAX1, &data[1]);
        read_adxl345_register(i2c_fd, REG_DATAY0, &data[2]);
        read_adxl345_register(i2c_fd, REG_DATAY1, &data[3]);
        read_adxl345_register(i2c_fd, REG_DATAZ0, &data[4]);
        read_adxl345_register(i2c_fd, REG_DATAZ1, &data[5]);

        printf("Accelerometer readings:\nx: %d.%02d g\ny: %d.%02d g\nz: %d.%02d g\n",
               data[0] >> 4, data[0] & 0x0F,
               data[1] >> 4, data[1] & 0x0F,
               data[2] >> 4, data[2] & 0x0F);

        usleep(100000);
    }

    gpiod_remove_callback(&line);
    gpiod_chip_unregister(&chip);
    close(i2c_fd);

    return 0;
}

