static void usage(void)
{
    fprintf(stderr, "Usage: %s\n", argv[0]);
    fprintf(stderr, "  Options:\n");
    fprintf(stderr, "    -q, --quiet  Suppress output\n");
    exit(EXIT_FAILURE);
}

