    int i;
    double seconds, start_time;
    int quiet = false;

    gpioInitialise();

    for (i = 1; i < argc; i++) {
        if (!strcmp(argv[i], "-q") || !strcmp(argv[i], "--quiet")) {
            quiet = true;
        } else {
            usage();
        }
    }

    if (gpioGetVersion() < 0) {
        fprintf(stderr, "pigpio library not available.\n");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed.\n");
        return 1;
    }

    if ((PWM_PINS & (gpioGetMode(PWM_PINS))) != PWM_PINS) {
        fprintf(stderr, "PWM pins not set to output mode.\n");
        gpioTerminate();
        return 1;
    }

    start_time = (double)time(NULL);

    for (;;) {
        if (quiet) {
            fflush(stdout);
        }

        for (i = 0; i < 3; i++) {
            int pin = (i == 0) ? PWM_PINS : (i == 1) ? (PWM_PINS << 8) : (PWM_PINS << 16);
            gpioSetMode(pin, PI_OUTPUT);
            gpioSetPWMfrequency(pin, 8000);
            gpioSetPWMrange(pin, 100);

            gpioWrite(pin, 50);
