        fprintf(stderr, "GPIO %d not available\n", GPIO_PIN);
        pigpio_terminate(fd);
        return 1;
    }

    // Set PWM parameters
    ret = pigpio_set_mode(fd, GPIO_PIN, PI_OUTPUT);
    if (ret < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_PIN);
        pigpio_terminate(fd);
        return 1;
    }

    ret = pigpio_set_PWM_frequency(fd, GPIO_PIN, PWM_FREQUENCY);
    if (ret < 0) {
        fprintf(stderr, "Failed to set PWM frequency for GPIO %d\n", GPIO_PIN);
        pigpio_terminate(fd);
        return 1;
    }

    ret = pigpio_set_PWM_range(fd, GPIO_PIN, 100);
    if (ret < 0) {
        fprintf(stderr, "Failed to set PWM range for GPIO %d\n", GPIO_PIN);
        pigpio_terminate(fd);
        return 1;
    }

    ret = pigpio_set_PWM_duty_cycle(fd, GPIO_PIN, PWM_DUTY_CYCLE);
    if (ret < 0) {
        fprintf(stderr, "Failed to set PWM duty cycle for GPIO %d\n", GPIO_PIN);
        pigpio_terminate(fd);
        return 1;
    }

    // Report initial state
    printf("Initial PWM state: %d%%\n", PWM_DUTY_CYCLE);

    // Main loop
    while (1) {
        // Report current state
        printf("Current PWM state: %d%%\n", pigpio_get_PWM_duty_cycle(fd, GPIO_PIN));
