#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <gpiod.h>

#define DEVICE "/dev/video0"
#define WIDTH 640
#define HEIGHT 480
#define BUFFER_SIZE (WIDTH * HEIGHT * 2)

int main(int argc, char *argv[]) {
    int fd, ret;
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    void *map;

    fd = open(DEVICE, O_RDWR);
    if (fd == -1) {
        perror("Failed to open device");
        return 1;
    }

    ret = ioctl(fd, VIDIOC_QUERYCAP, &cap);
    if (ret == -1) {
        perror("Failed to query device capabilities");
        close(fd);
        return 1;
    }

    ret = ioctl(fd, VIDIOC_S_FMT, &fmt);
    if (ret == -1) {
        perror("Failed to set format");
        close(fd);
        return 1;
    }

    fmt.type = V4L2_BUF_TYPE_IMAGE;
    fmt.fmt.pix.width = WIDTH;
    fmt.fmt.pix.height = HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_BGR;
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    ret = ioctl(fd, VIDIOC_S_FMT, &fmt);
    if (ret == -1) {
        perror("Failed to set format");
        close(fd);
        return 1;
    }

    map = mmap(NULL, BUFFER_SIZE, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    if (map == MAP_FAILED) {
        perror("Failed to mmap");
        close(fd);
        return 1;
    }

    ret = ioctl(fd, VIDIOC_DQBUF, &ret);
    if (ret == -1) {
        perror("Failed to dequeue buffer");
        munmap(map, BUFFER_SIZE);
        close(fd);
        return 1;
    }

    ret = ioctl(fd, VIDIOC_QBUF, map);
    if (ret == -1) {
        perror("Failed to queue buffer");
        munmap(map, BUFFER_SIZE);
        close(fd);
        return 1;
    }

    ret = ioctl(fd, VIDIOC_STREAMON, NULL);
    if (ret == -1) {
        perror("Failed to start streaming");
        ioctl(fd, VIDIOC_DQBUF, &ret);
        munmap(map, BUFFER_SIZE);
        close(fd);
        return 1;
    }

    ret = read(fd, map, BUFFER_SIZE);
    if (ret == -1) {
        perror("Failed to read from device");
        ioctl(fd, VIDIOC_STREAMOFF, NULL);
        munmap(map, BUFFER_SIZE);
        close(fd);
        return 1;
    }

    ioctl(fd, VIDIOC_STREAMOFF, NULL);
    munmap(map, BUFFER_SIZE);
    close(fd);

    FILE *fp = fopen("image.bmp", "wb");
    if (!fp) {
        perror("Failed to open output file");
        return 1;
    }

    fwrite(map, BUFFER_SIZE, 1, fp);
    fclose(fp);

    return 0;
}

