        gpiod_line_trigger(line_tim.line, 1);
        delay(1000000); // 1ms pulse
        gpiod_line_trigger(line_tim.line, 0);

        uint64_t duration = (end_time - start_time) / 1000000.0;
        double distance = duration * 0.0343 / 2; // Speed of sound is 343m/s

