int init_camera(void) {
    camera_fd = open("/dev/video0", O_RDWR);
    if (camera_fd == -1) {
        perror("Failed to open camera device");
        return -1;
    }

    struct v4l2_capability cap;
    if (ioctl(camera_fd, VIDIOC_QUERYCAP, &cap) == -1) {
        perror("Failed to query camera capabilities");
        cleanup();
        return -1;
    }

    if ((cap.cap.capabilities & V4L2_CAP_TUNER) == 0) {
        printf("Camera device found.\n");
    } else {
        printf("Camera device not found.\n");
        return -1;
    }

    struct v4l2_fmtdesc fmt;
    fmt.index = 0;
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(camera_fd, VIDIOC_ENUM_FMT, &fmt) == -1) {
        perror("Failed to enumerate formats");
        cleanup();
        return -1;
    }

    struct v4l2_frmt vfmt;
    vfmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    vfmt.fmt.pix.width = WIDTH;
    vfmt.fmt.pix.height = HEIGHT;
    vfmt.fmt.pix.pixelformat = V4L2_PIX_FMT_BGR;
    vfmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (ioctl(camera_fd, VIDIOC_S_FMT, &vfmt) == -1) {
        perror("Failed to set format");
        cleanup();
        return -1;
    }

    return 0;
}

void capture_image(void) {
    struct v4l2_buffer buf;
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(camera_fd, VIDIOC_REQBUFS, &buf) == -1) {
        perror("Failed to request buffer");
        return;
    }

    if (mmap(buffer, BUFFER_SIZE, PROT_READ | PROT_WRITE, MAP_SHARED, camera_fd, 0) == -1) {
        perror("Failed to mmap buffer");
        return;
    }

    if (ioctl(camera_fd, VIDIOC_DQBUF, &buf) == -1) {
        perror("Failed to dequeue buffer");
        return;
    }

    FILE *fp = fopen("captured_image.bmp", "wb");
    if (!fp) {
        perror("Failed to open output file");
        munmap(buffer, BUFFER_SIZE);
        return;
    }

    fwrite(buffer, 1, BUFFER_SIZE, fp);
    fclose(fp);
    munmap(buffer, BUFFER_SIZE);
}

int main(void) {
    if (init_camera() == -1) {
        return 1;
    }

    atexit(cleanup);

    while (1) {
        capture_image();
        usleep(CAPTURE_INTERVAL_SEC * 1e6);
    }

    return 0;
}

