#define ADS1115_REG_RESULT_LOW (0x01)
#define ADS1115_REG_RESULT_HIGH (0x02)
#define ADS1115_GAIN_ONE (0x00)
#define ADS1115_GAIN_TWO (0x01)
#define ADS1115_GAIN_FOUR (0x02)
#define ADS1115_GAIN_EIGHT (0x03)

int ads_init(int fd) {
    if (ioctl(fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        return -1;
    }

    struct gpiod_chip chip;
    gpiod_chip_init(&chip, "ads1115");

    struct gpiod_line config = gpiod_chip_get_line(&chip, "config");
    struct gpiod_line result_low = gpiod_chip_get_line(&chip, "result-low");
    struct gpiod_line result_high = gpiod_chip_get_line(&chip, "result-high");

    if (gpiod_line_request_one(&config, "ads1115-config") < 0 ||
        gpiod_line_request_one(&result_low, "ads1115-result-low") < 0 ||
        gpiod_line_request_one(&result_high, "ads1115-result-high") < 0) {
        fprintf(stderr, "Failed to request GPIO pins\n");
        return -1;
    }

    gpiod_line_direction_input(&config);
    gpiod_line_direction_output(&result_low);
    gpiod_line_direction_output(&result_high);

    return 0;
}

int ads_read(int fd, int16_t *value) {
    uint8_t config = ADS1115_REG_CONFIG | ADS1115_GAIN_ONE;
    if (write(fd, &config, sizeof(config)) != sizeof(config)) {
        perror("Failed to write to ADS1115");
        return -1;
    }

    uint8_t result_low, result_high;
    if (read(fd, &result_low, sizeof(result_low)) != sizeof(result_low)) {
        perror("Failed to read from ADS1115");
        return -1;
    }

    if (read(fd, &result_high, sizeof(result_high)) != sizeof(result_high)) {
        perror("Failed to read from ADS1115");
        return -1;
    }

    *value = (result_high << 8) | result_low;
    return 0;
}

