}

int init_i2c() {
    int file;
    file = open("/dev/i2c-1", O_RDWR);
    CHECK_ERROR(file);

    ioctl(file, I2C_SLAVE, I2C_ADDR);
    CHECK_ERROR(ioctl(file, I2C_SLAVE));

    return file;
}

void cleanup_i2c(int file) {
    close(file);
}

void init_gpio() {
    gpioInitialise();
    gpioSetMode(RS, PI_OUTPUT);
    gpioSetMode(E, PI_OUTPUT);
    gpioSetMode(D4, PI_OUTPUT);
    gpioSetMode(D5, PI_OUTPUT);
    gpioSetMode(D6, PI_OUTPUT);
    gpioSetMode(D7, PI_OUTPUT);
    gpioSetMode(BACKLIGHT, PI_OUTPUT);

    gpioWrite(RS, 0);
    gpioWrite(E, 0);
    gpioWrite(D4, 0);
    gpioWrite(D5, 0);
    gpioWrite(D6, 0);
    gpioWrite(D7, 0);
    gpioWrite(BACKLIGHT, 0);
}

void cleanup_gpio() {
    gpioTerminate();
}

void send_byte(int file, unsigned char byte) {
    for (int i = 0; i < 8; i++) {
        gpioWrite(RS, (byte & (1 << i)) >> i);
        gpioWrite(E, 1);
        delay_ms(1);
        gpioWrite(E, 0);
    }
}

void send_string(int file, char *str) {
    while (*str) {
        send_byte(file, *str++);
    }
}

