#define MPU6050_ADDR 0x68
#define ACCEL_XOUT_H 0x3B
#define ACCEL_XOUT_L 0x3C
#define GYRO_XOUT_H 0x43
#define GYRO_XOUT_L 0x44

#define READ_PID 0x3C

int main() {
    int fd, res;
    char filename[20] = "/dev/i2c-1";
    struct i2c_rdwr_ioctl_data rdwr_data;
    struct i2c_msg messages[2];
    int count = 0;

    // Open I2C device
    fd = open(filename, O_RDWR);
    if (fd < 0) {
        perror("Failed to open i2c bus");
        return 1;
    }

    // Set I2C address
    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(fd);
        return 1;
    }

    // Prepare read command
    messages[0].addr = ACCEL_XOUT_H;
    messages[0].flags = 0;
    messages[0].len = 1;
    messages[0].buf = &rdwr_data.i2c_rdbt;

    messages[1].addr = ACCEL_XOUT_L;
    messages[1].flags = CIRC_BUFF;
    messages[1].len = 1;
    messages[1].buf = &rdwr_data.i2c_wdbt;

    // Perform read
    rdwr_data.msgs = messages;
    rdwr_data.nmsgs = 2;
    res = ioctl(fd, I2C_RDWR, &rdwr_data);
    if (res < 0) {
        perror("Error during i2c transfer");
        close(fd);
        return 1;
    }

    // Read accelerometer X value
    int16_t ax = ((rdwr_data.i2c_rdbt[0] << 8) | rdwr_data.i2c_wdbt[0]);

    // Loop for 100 readings
    for (count = 0; count < 100; count++) {
        printf("Accel X: %d\n", ax);
        // Perform another read to get updated values
        rdwr_data.i2c_rdbt[0] = ACCEL_XOUT_H;
        rdwr_data.i2c_wdbt[0] = 0;
        res = ioctl(fd, I2C_RDWR, &rdwr_data);
        if (res < 0) {
            perror("Error during i2c transfer");
            close(fd);
            return 1;
        }
        ax = ((rdwr_data.i2c_rdbt[0] << 8) | rdwr_data.i2c_wdbt[0]);
    }

    // Close I2C device
    close(fd);

    return 0;
}

