static int setup_gpio(int gpio) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    ret = gpiod_chip_open(&chip, "gpiochip0");
    if (ret < 0) {
        fprintf(stderr, "Failed to open gpiochip0\n");
        return ret;
    }

    ret = gpiod_chip_get_line(chip, gpio, 0, &line);
    if (ret < 0) {
        gpiod_chip_close(chip);
        return ret;
    }

    ret = gpiod_line_export(line, NULL);
    if (ret < 0) {
        gpiod_line_unref(line);
        gpiod_chip_close(chip);
        return ret;
    }

    return 0;
}

static void cleanup_gpio(struct gpiod_line *line) {
    gpiod_line_unref(line);
    gpiod_chip_close(line->chip);
}

static void toggle_gpio(struct gpiod_line *line) {
    int ret;
    ret = gpiod_line_start(line);
    if (ret < 0) {
        fprintf(stderr, "Failed to start line\n");
        return;
    }

    ret = gpiod_line_direction_input(line);
    if (ret < 0) {
        fprintf(stderr, "Failed to set direction to input\n");
        gpiod_line_stop(line);
        return;
    }

    ret = gpiod_line_read(line, &line->value);
    if (ret < 0) {
        fprintf(stderr, "Failed to read line value\n");
        gpiod_line_stop(line);
        return;
    }

    if (line->value) {
        printf("GPIO %d is HIGH\n", gpio);
        ret = gpiod_line_direction_output(line);
        if (ret < 0) {
            fprintf(stderr, "Failed to set direction to output\n");
            gpiod_line_stop(line);
            return;
        }
        ret = gpiod_line_prepare_output(line, 0);
        if (ret < 0) {
            fprintf(stderr, "Failed to prepare output\n");
            gpiod_line_stop(line);
            return;
        }
        ret = gpiod_line_write(line, 0);
        if (ret < 0) {
            fprintf(stderr, "Failed to write to line\n");
            gpiod_line_stop(line);
            return;
        }
    } else {
        printf("GPIO %d is LOW\n", gpio);
        ret = gpiod_line_direction_output(line);
        if (ret < 0) {
            fprintf(stderr, "Failed to set direction to output\n");
            gpiod_line_stop(line);
            return;
        }
        ret = gpiod_line_prepare_output(line, 1);
        if (ret < 0) {
            fprintf(stderr, "Failed to prepare output\n");
            gpiod_line_stop(line);
            return;
        }
        ret = gpiod_line_write(line, 1);
        if (ret < 0) {
            fprintf(stderr, "Failed to write to line\n");
            gpiod_line_stop(line);
            return;
        }
    }

    gpiod_line_stop(line);
}

int main(int argc, char *argv[]) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;
    int gpio;

    if (argc != 1) {
        fprintf(stderr, "Usage: %s\n", argv[0]);
        return EXIT_FAILURE;
    }

    ret = setup_gpio(GPIO_14);
    if (ret < 0) {
        return ret;
    }
    gpio = GPIO_14;

    while (1) {
        toggle_gpio(line);
        sleep(CHECK_INTERVAL);
        gpio++;
        if (gpio == GPIO_15) {
            gpio = GPIO_14;
        }
    }

    cleanup_gpio(line);
    return EXIT_SUCCESS;
}

