#include <stdlib.h>
#include <unistd.h>
#include <gpiod.h>

#define TRIG_PIN 23
#define ECHO_PIN 24
#define DELAY 0.2

int main() {
    struct gpiod_chip chip;
    struct gpiod_line line;
    struct timespec period;
    int ret;

    // Initialize libgpiod
    ret = gpiod_chip_open(&chip, "gpiochip0");
    if (ret < 0) {
        fprintf(stderr, "Failed to open gpiochip0\n");
        return ret;
    }

    // Get the lines
    ret = gpiod_chip_get_line(&line, &chip, TRIG_PIN);
    if (ret < 0) {
        fprintf(stderr, "Failed to get line %d\n", TRIG_PIN);
        gpiod_chip_close(chip);
        return ret;
    }

    // Set up the line for output (trigger)
    gpiod_line_export(line);
    ret = gpiod_set_value(line, 1);
    if (ret < 0) {
        fprintf(stderr, "Failed to set trigger line to high\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return ret;
    }

    // Set up the period for measurement
    period.tv_sec = 0;
    period.tv_nsec = 100000000; // 0.1 seconds

    while (1) {
        // Set trigger line low for 2us
        ret = gpiod_set_value(line, 0);
        if (ret < 0) {
            fprintf(stderr, "Failed to set trigger line to low\n");
            break;
        }
        usleep(2000); // 2us

        // Set trigger line high for 10us
        ret = gpiod_set_value(line, 1);
        if (ret < 0) {
            fprintf(stderr, "Failed to set trigger line to high\n");
            break;
        }
        usleep(10000); // 10us

        // Wait for echo line to go high
        ret = gpiod_get_value(line);
        if (ret < 0) {
            fprintf(stderr, "Failed to read echo line\n");
            break;
        }
        while (!gpiod_get_value(line)); // Wait for echo line to go high

        // Measure the time until echo line goes low
        ret = gpiod_get_value(line);
        if (ret < 0) {
            fprintf(stderr, "Failed to read echo line\n");
            break;
        }
        while (gpiod_get_value(line)); // Wait for echo line to go low

        // Calculate distance
        unsigned long duration_us = (unsigned long)(period.tv_sec * 1000000 + period.tv_nsec / 1000);
        float distance_cm = duration_us / 58; // Speed of sound is 58cm in microseconds

        printf("Distance: %.2f cm\n", distance_cm);

        // Delay before next measurement
        nanosleep(&period, NULL);
    }

    // Release the line and close the chip
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return 0;
}

