#define ADS1115_ADDR 0x48
#define NUM_READINGS 10

struct ads_context ads_ctx;
struct mqtt mqtt_client;

void ads_init() {
    if (gpiod_in_create("ads_data", "GPIO17", GPIOD_IN_OPEN_DRAIN) == -1) {
        perror("Failed to create GPIO for ADS1115 data pin");
        exit(EXIT_FAILURE);
    }
    if (pigo_init() == -1) {
        perror("Failed to initialize pigpio library");
        exit(EXIT_FAILURE);
    }
    if (ads_create_context(&ads_ctx) != ADS_OK) {
        fprintf(stderr, "Failed to create ADS1115 context\n");
        exit(EXIT_FAILURE);
    }
    if (ads_set_shared_mem_addr(&ads_ctx, ADS1115_ADDR) != ADS_OK) {
        fprintf(stderr, "Failed to set ADS1115 address\n");
        exit(EXIT_FAILURE);
    }
    if (ads_set_conv_rate(&ads_ctx, ADS1115_CONV_RATE_128SPS) != ADS_OK) {
        fprintf(stderr, "Failed to set conversion rate\n");
        exit(EXIT_FAILURE);
    }
}

void mqtt_init(char *broker, char *topic, char *client_id) {
    mqtt_client = mqtt_client_new(MQTT_CLIENT_OPTION_CLEAN_SESSION, 0);
    if (mqtt_client == NULL) {
        fprintf(stderr, "Failed to create MQTT client\n");
        exit(EXIT_FAILURE);
    }
    if (mqtt_connect(mqtt_client, broker, 1883, MQTT_CLIENT_OPTION_USER_DATA, NULL) != MQTT_ERR_SUCCESS) {
        fprintf(stderr, "Failed to connect to MQTT broker\n");
        exit(EXIT_FAILURE);
    }
    if (mqtt_subscribe(mqtt_client, topic, 0) != MQTT_ERR_SUCCESS) {
        fprintf(stderr, "Failed to subscribe to topic\n");
        exit(EXIT_FAILURE);
    }
}

void ads_read(float *values) {
    uint8_t data[8];
    if (ads_read_bulk(&ads_ctx, data, 8) != 8) {
        fprintf(stderr, "Failed to read from ADS1115\n");
        exit(EXIT_FAILURE);
    }
    for (int i = 0; i < 4; i++) {
        values[i] = (float)data[i * 2] + ((float)data[i * 2 + 1] << 8) / 32768.0;
    }
}

void publish_readings(float *values) {
    char msg[50];
    for (int i = 0; i < 4; i++) {
        snprintf(msg, sizeof(msg), "Channel %d: %f\n", i, values[i]);
        if (mqtt_publish(mqtt_client, NULL, msg) != MQTT_ERR_SUCCESS) {
            fprintf(stderr, "Failed to publish message\n");
            exit(EXIT_FAILURE);
        }
    }
}

int main(int argc, char *argv[]) {
    if (argc != 4) {
        fprintf(stderr, "Usage: %s <broker> <topic> <client_id>\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    ads_init();
    mqtt_init(argv[1], argv[2], argv[3]);

    float values[NUM_READINGS];
    for (int i = 0; i < NUM_READINGS; i++) {
        ads_read(values);
        publish_readings(values);
        sleep(1);
    }

    mqtt_disconnect(mqtt_client, 100);
    mqtt_client_destroy(&mqtt_client);
    pigo_terminate();
    gpiod_deinit();

    return 0;
}

