    if (gpiod_chip_open(&chip, "GPIO17-GPIO18") < 0) {
        fprintf(stderr, "Error: Device not found.\n");
        return 1;
    }

    for (i = 0; i < ARRAY_SIZE(OUTPUT_PINS); i++) {
