        if (!line) {
            fprintf(stderr, "Error: Failed to get line for pin %d.\n", OUTPUT_PINS[i]);
            gpiod_chip_close(chip);
            return 1;
        }

        gpiod_line_export(line);
        gpiod_line_set_direction(line, GPIO_DIR_OUT);
    }

    while (1) {
