            line = gpiod_chip_get_line(chip, OUTPUT_PINS[i]);
            if (!line) {
                fprintf(stderr, "Error: Line disappeared.\n");
                goto cleanup;
            }

            gpiod_line_trigger(line, 1);
            usleep(REPORT_INTERVAL * 1e6);
            gpiod_line_trigger(line, 0);

