#define SERIAL_DEVICE "/dev/serial0"
#define BAUD_RATE B9600

static volatile sig_atomic_t sigint = 0;

static void signal_handler(int signum) {
    sigint = signum;
}

int main(int argc, char *argv[]) {
    int serial_fd = -1;
    struct termios termios;

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Open serial device
    serial_fd = open(SERIAL_DEVICE, O_RDWR | O_NOCTTY | O_NDELAY);
    if (serial_fd == -1) {
        perror("open");
        return 1;
    }

    // Set serial port parameters
    if (tcgetattr(serial_fd, &termios) == -1) {
        perror("tcgetattr");
        return 1;
    }

    cfsetospeed(&termios, BAUD_RATE);
    cfsetispeed(&termios, BAUD_RATE);

    termios.c_cflag |= (CLOCAL | CREAD);
    termios.c_cflag &= ~PARENB;
    termios.c_cflag &= ~CSTOPB;
    termios.c_cflag &= ~CSIZE;
    termios.c_cflag |= CS8;

    termios.c_lflag = 0;
    termios.c_oflag = 0;

    if (tcsetattr(serial_fd, TCSANOW, &termios) == -1) {
        perror("tcsetattr");
        return 1;
    }

    // Read from serial port
    char buffer[256];
    ssize_t bytes_read;
    while (sigint == 0) {
        bytes_read = read(serial_fd, buffer, sizeof(buffer));
        if (bytes_read > 0) {
            buffer[bytes_read] = '\0';
            printf("Received: %s\n", buffer);
