        return -1;
    }

    *x = i2c_rdwr(i2c_fd, &GPIOD_DEV(0), GPIOD_IN, REG_ACCEL_XOUT_H, 2, NULL, 0);
    *y = i2c_rdwr(i2c_fd, &GPIOD_DEV(0), GPIOD_IN, REG_ACCEL_YOUT_H, 2, NULL, 0);
    *z = i2c_rdwr(i2c_fd, &GPIOD_DEV(0), GPIOD_IN, REG_ACCEL_ZOUT_H, 2, NULL, 0);

