#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <gpiod.h>

#define BMP280_ADDR 0x76
#define I2C_ADDR_SIZE 1
#define I2C_CMD_SIZE 1
#define I2C_READ_SIZE 2

int i2c_fd;
int bmp280_present = 0;

int read_bmp280_data(uint8_t *data) {
    if (!bmp280_present)
        return -1;

    if (write(i2c_fd, "R", 1) != 1) {
        perror("Failed to write to I2C device");
        return -1;
    }

    if (read(i2c_Fd, data, I2C_READ_SIZE) != I2C_READ_SIZE) {
        perror("Failed to read from I2C device");
        return -1;
    }

    return 0;
}

int main() {
    struct i2c_rdwr_ioctl_data rdwr_data;
    struct gpiod_chip chip;
    struct gpiod_line line;
    int ret;

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BMP280_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return 1;
    }

    rdwr_data.u8 = (uint8_t *)"R";
    rdwr_data.u8len = 1;
    rdwr_data.u32len = 0;

    ret = ioctl(i2c_fd, I2C_RDWR, &rdwr_data);
    if (ret < 0) {
        perror("Failed to perform I2C read");
        close(i2c_fd);
        return 1;
    }

    if (ret != 1) {
        bmp280_present = 0;
    } else {
        bmp280_present = 1;
    }

    if (!bmp280_present) {
        fprintf(stderr, "BMP280 not found at address 0x76\n");
        close(i2c_fd);
        return 1;
    }

    close(i2c_fd);

    gpiod_chip_register(&chip, "BMP280_INT");
    line = gpiod_chip_get_line(&chip, "BMP280_INT");
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line for BMP280 interrupt\n");
        return 1;
    }

    gpiod_line_export(&line, NULL);
    gpiod_line_request_add(&line, "wakeup");

    while (1) {
        uint8_t data[I2C_READ_SIZE];
        read_bmp280_data(data);

        printf("Temperature: %0.2f C, Pressure: %0.2f hPa\n", data[0], data[1]);

        sleep(5);
    }

    gpiod_line_release(&line);
    gpiod_chip_unregister(&chip);

    return 0;
}

