#include "mqtt/mqtt.h"

#define SENSOR_GPIO 18
#define MQTT_BROKER "localhost"
#define MQTT_TOPIC "test/topic"

struct gpiod_chip *chip;
struct gpiod_line *line;
mqtt_client_handle_t client;

void read_sensor_and_publish() {
    while (1) {
        int value = gpiod_read(line);
        char message[50];
        snprintf(message, sizeof(message), "Sensor reading: %d", value);
        mqtt_publish(&client, MQTT_BROKER, MQTT_TOPIC, message, strlen(message));
        usleep(1000000); // Sleep for 1 second
    }
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <mqtt-broker>\n", argv[0]);
        return EXIT_FAILURE;
    }

    MQTT_OPT_CALLBACK_MESSAGE mqtt_message_callback = {0};
    mqtt_message_callback.message_callback = NULL;
    mqtt_message_callback.message_callback_context = NULL;

    MQTT_OPT_CALLBACK_CONNECT mqtt_connect_callback = {0};
    mqtt_connect_callback.connect_callback = NULL;
    mqtt_connect_callback.connect_callback_context = NULL;

    MQTT_OPT_CALLBACK_DISCONNECT mqtt_disconnect_callback = {0};
    mqtt_disconnect_callback.disconnect_callback = NULL;
    mqtt_disconnect_callback.disconnect_callback_context = NULL;

    MQTT_OPT_CALLBACK_SUBSCRIBE mqtt_subscribe_callback = {0};
    mqtt_subscribe_callback.subscribe_callback = NULL;
    mqtt_subscribe_callback.subscribe_callback_context = NULL;

    MQTT_OPT_CALLBACK_UNSUBSCRIBE mqtt_unsubscribe_callback = {0};
    mqtt_unsubscribe_callback.unsubscribe_callback = NULL;
    mqtt_unsubscribe_callback.unsubscribe_callback_context = NULL;

    MQTT_OPT_CALLBACK_ERROR mqtt_error_callback = {0};
    mqtt_error_callback.error_callback = NULL;
    mqtt_error_callback.error_callback_context = NULL;

    MQTT_OPT_CALLBACK_USE mqtt_opts[] = {
        MQTT_OPT_CALLBACK_MESSAGE(&mqtt_message_callback),
        MQTT_OPT_CALLBACK_CONNECT(&mqtt_connect_callback),
        MQTT_OPT_CALLBACK_DISCONNECT(&mqtt_disconnect_callback),
        MQTT_OPT_CALLBACK_SUBSCRIBE(&mqtt_subscribe_callback),
        MQTT_OPT_CALLBACK_UNSUBSCRIBE(&mqtt_unsubscribe_callback),
        MQTT_OPT_CALLBACK_ERROR(&mqtt_error_callback)
    };

    int mqtt_opts_count = sizeof(mqtt_opts) / sizeof(mqtt_opts[0]);

    int ret = mqtt_loop_start(mqtt_opts, mqtt_opts_count);
    if (ret != MQTT_SUCCESS) {
        fprintf(stderr, "Failed to start MQTT loop: %d\n", ret);
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open(NULL);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, SENSOR_GPIO);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    gpiod_line_export(line);

    ret = mqtt_connect(&client, MQTT_BROKER, "client_id", MQTT_CLIENT_PICO_TLS);
    if (ret != MQTT_SUCCESS) {
        fprintf(stderr, "Failed to connect to MQTT broker: %d\n", ret);
        gpiod_line_unexport(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = mqtt_subscribe(&client, MQTT_BROKER, MQTT_TOPIC, 0);
    if (ret != MQTT_SUCCESS) {
        fprintf(stderr, "Failed to subscribe to MQTT topic: %d\n", ret);
        mqtt_disconnect(&client, 1000);
        gpiod_line_unexport(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    read_sensor_and_publish();

    mqtt_disconnect(&client, 1000);
    gpiod_line_unexport(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

