    int setup_error = 0;

    // Initialise pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio library\n");
        goto finish;
    }

    // Set up GPIOs as output
    for (i = 0; i < sizeof(PIN_LIST) / sizeof(PIN_LIST[0]); i++) {
        int pin = PIN_LIST[i];
        if (gpioSetMode(pin, PI_OUTPUT) < 0) {
            fprintf(stderr, "Failed to set GPIO %d as output\n", pin);
            setup_error = 1;
            goto finish;
        }
    }

    // Set PWM frequency
    if (gpioSetPWMfrequency(1000000) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        setup_error = 1;
        goto finish;
    }

    // Set PWM duty cycle (50% duty cycle)
    for (i = 0; i < sizeof(PIN_LIST) / sizeof(PIN_LIST[0]); i++) {
        int pin = PIN_LIST[i];
        if (gpioPWM(pin, 500000) < 0) {
            fprintf(stderr, "Failed to set PWM on GPIO %d\n", pin);
            setup_error = 1;
            goto finish;
        }
    }

    // Report the state
    for (i = 0; i < sizeof(PIN_LIST) / sizeof(PIN_LIST[0]); i++) {
        int pin = PIN_LIST[i];
        if (gpioGetPWMduty(pin) == 500000) {
            printf("GPIO%d is ON\n", pin);
        } else {
            printf("GPIO%d is OFF\n", pin);
