#define PWM_PINS 3
#define PWM_PERIOD 10000  // 50Hz
#define PWM_DUTY_CYCLE 5000  // 50% duty cycle

int main(int argc, char **argv) {
    int pid = pigpio_initialise();
    if (pid < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    const int pins[] = {17, 22, 27};
    for (int i = 0; i < PWM_PINS; i++) {
        if (gpioInitialise() < 0) {
            fprintf(stderr, "gpioInitialise failed\n");
            pigpio_terminate(pid);
            return 1;
        }
        if (gpioSetMode(pins[i], PI_OUTPUT) < 0) {
            fprintf(stderr, "gpioSetMode failed\n");
            gpioTerminate();
            pigpio_terminate(pid);
            return 1;
        }
    }

    while (1) {
        for (int i = 0; i < PWM_PINS; i++) {
            if (pigpio_set_PWM_range(pins[i], PWM_PERIOD) < 0) {
                fprintf(stderr, "set_PWM_range failed\n");
