                break;
            }
            printf("PWM state on %d: duty cycle %d%%\n", pins[i], PWM_DUTY_CYCLE);
            usleep(PWM_PERIOD / 10);  // Repeat every 0.05 seconds
        }
    }

    for (int i = 0; i < PWM_PINS; i++) {
