#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <linux/videodev2.h>
#include <gpiod.h>

#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define IMAGE_SIZE (IMAGE_WIDTH * IMAGE_HEIGHT * 2)

int camera_fd = -1;
char image_buffer[IMAGE_SIZE];

int init_camera() {
    camera_fd = open("/dev/video0", O_RDWR);
    if (camera_fd < 0) {
        perror("Failed to open camera device");
        return -1;
    }

    struct v4l2_capability cap;
    if (ioctl(camera_fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Failed to query camera capabilities");
        close(camera_fd);
        return -1;
    }

    if ((cap.cap.caps & V4L2_CAP_TUNER) == 0) {
        printf("Camera device found.\n");
    } else {
        printf("No camera device found.\n");
        return -1;
    }

    return 0;
}

void cleanup_camera() {
    if (camera_fd >= 0) {
        close(camera_fd);
    }
}

int capture_image(void) {
    struct v4l2_buffer buf;
    struct v4l2_requestbuffers rbqs;

    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_DMABUF;
    buf.index = 0;

    rbqs.count = 1;
    rbqs.pattern = V4L2_BUF_MODE_SINGLE_PLANAR;
    rbqs.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    rbqs.memory = V4L2_MEMORY_DMABUF;
    rbqs.reserved[0] = 0;
    rbqs.reserved[1] = 0;

    if (ioctl(camera_fd, VIDIOC_REQBUFS, &rbqs) < 0) {
        perror("Failed to request buffers");
        return -1;
    }

    if (ioctl(camera_fd, VIDIOC_DQBUF, &buf) < 0) {
        perror("Failed to dequeue buffer");
        return -1;
    }

    // Read data from the buffer
    if (read(camera_fd, image_buffer, IMAGE_SIZE) != IMAGE_SIZE) {
        perror("Failed to read image data");
        return -1;
    }

    ioctl(camera_fd, VIDIOC_QBUF, &buf);

    return 0;
}

int main(int argc, char *argv[]) {
    if (init_camera() < 0) {
        return 1;
    }

    while (1) {
        if (capture_image() < 0) {
            break;
        }

        FILE *file = fopen("captured_image.raw", "wb");
        if (!file) {
            perror("Failed to open output file");
            break;
        }

        fwrite(image_buffer, 1, IMAGE_SIZE, file);
        fclose(file);

        sleep(1);
    }

    cleanup_camera();
    return 0;
}

