#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <gpiod.h>
#include <paho-mqtt.h>

#define CHANNEL 0
#define SPI_DEV "/dev/spidev0.0"
#define MQTT_BROKER "mqtt.example.com"
#define MQTT_TOPIC "mcp3008/readings"

struct mcp3008_data {
    int fd;
    int channel;
    uint16_t value;
};

static int mcp3008_read(struct mcp3008_data *data) {
    char cmd[3] = {0x01, 0x00, 0x00};
    cmd[1] = (data->channel >> 4) & 0x03;
    cmd[1] |= (data->channel & 0x08) >> 3;
    cmd[1] |= (data->channel & 0x04) >> 2;
    cmd[1] |= (data->channel & 0x02) >> 1;
    cmd[1] |= (data->channel & 0x01);

    spi_transfer(data->fd, cmd, 3);
    spi_transfer(data->fd, NULL, 0);

    data->value = (data->fd[3] << 8) | data->fd[4];
    return 0;
}

static int spi_transfer(int fd, const uint8_t *tx_buf, size_t tx_len) {
    uint8_t rx_buf[10];
    ssize_t len;

    len = write(fd, tx_buf, tx_len);
    if (len < 0) {
        perror("SPI write");
        return -1;
    }

    len = read(fd, rx_buf, sizeof(rx_buf));
    if (len < 0) {
        perror("SPI read");
        return -1;
    }

    return len;
}

static int init_mcp3008(struct mcp3008_data *data) {
    data->fd = spi_open(SPI_DEV, SPI_CS0);
    if (!data->fd) {
        perror("SPI open");
        return -1;
    }

    data->channel = CHANNEL;
    return mcp3008_read(data);
}

static void cleanup_mcp3008(struct mcp3008_data *data) {
    spi_close(data->fd);
    data->fd = -1;
}

static void publish_mqtt(const uint16_t value) {
    MQTT_Client mqtt_client;
    MQTT_Property *prop;

    mqtt_client.uri = MQTT_BROKER;
    mqtt_client.uri_len = strlen(MQTT_BROKER);
    mqtt_client.client_id = "mcp3008_publisher";
    mqtt_client.client_id_len = strlen(mqtt_client.client_id);
    mqtt_client.keepalive_interval = 60;
    mqtt_client.clean_session = 1;

    prop = malloc(sizeof(MQTT_Property));
    prop->key = MQTT_PROPERTY_LEVEL;
    prop->value.level = MQTT_QOS0;
    mqtt_client.properties = prop;
    mqtt_client.property_count = 1;

    mqtt_client.connect_callback = NULL;
    mqtt_client.disconnect_callback = NULL;
    mqtt_client.message_callback = NULL;
    mqtt_client.log_callback = NULL;

    if (mqtt_client.connect(&mqtt_client) != MQTT_ERR_SUCCESS) {
        fprintf(stderr, "MQTT connect failed\n");
        return;
    }

    char msg[30];
    sprintf(msg, "%u", value);
    if (mqtt_client.publish(mqtt_client.client_id, MQTT_TOPIC, msg, strlen(msg), 0) != MQTT_ERR_SUCCESS) {
        fprintf(stderr, "MQTT publish failed\n");
    }

    mqtt_client.disconnect(&mqtt_client);
    free(prop);
}

int main(int argc, char *argv[]) {
    struct mcp3008_data data;
    int ret;

    ret = init_mcp3008(&data);
    if (ret < 0) {
        cleanup_mcp3008(&data);
        return EXIT_FAILURE;
    }

    while (1) {
        ret = mcp3008_read(&data);
        if (ret < 0) {
            cleanup_mcp3008(&data);
            return EXIT_FAILURE;
        }

        publish_mqtt(data.value);
        usleep(1000000); // Sleep for 1 second
    }

    cleanup_mcp3008(&data);
    return EXIT_SUCCESS;
}

