        printf("PWM state for GPIO %d: %d\n", gpio_pins[i], 1);
    }

    success = 1;

exit_clean:
    // Release resources
    if (!success) {
        gpioTerminate();
    }

    for (i = 0; i < NUM_PINS; i++) {
        gpioPWM(gpio_pins[i], 0); // Stop PWM
    }

    gpioTerminate();

    return success ? EXIT_SUCCESS : EXIT_FAILURE;
}

