#include <linux/videodev2.h>
#include <gpiod.h>

#define CAPTURE_INTERVAL_SEC 0.1
#define WIDTH 640
#define HEIGHT 480
#define FPS 10

static int camera_fd = -1;
static struct v4l2_capability cap;
static struct v4l2_format fmt;
static void *map;
static char filename[256];

static int open_camera() {
    camera_fd = v4l2_open("/dev/video0", O_RDWR, 0);
    if (camera_fd < 0) {
        perror("Failed to open camera device");
        return -1;
    }

    if (ioctl(camera_fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Failed to query camera capabilities");
        close(camera_fd);
        camera_fd = -1;
        return -1;
    }

    fmt.type = V4L2_BUF_TYPE_IMAGE;
    fmt.fmt.pix.width = WIDTH;
    fmt.fmt.pix.height = HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_BGR;
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (ioctl(camera_fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Failed to set format");
        close(camera_fd);
        camera_fd = -1;
        return -1;
    }

    map = mmap(NULL, v4l2_get_fmt(camera_fd, &fmt), PROT_READ | PROT_WRITE, MAP_SHARED, camera_fd, 0);
    if (map == MAP_FAILED) {
        perror("Failed to mmap");
        close(camera_fd);
        camera_fd = -1;
        return -1;
    }

    return 0;
}

static void close_camera() {
    if (map) {
        munmap(map, v4l2_get_fmt(camera_fd, &fmt).buf.size);
        map = NULL;
    }

    if (camera_fd >= 0) {
        close(camera_fd);
        camera_fd = -1;
    }
}

static int capture_image(const char *filename) {
    struct timespec ts;
    ts.tv_sec = 0;
    ts.tv_nsec = 100000000; // 0.1 seconds

    if (ioctl(camera_fd, VIDIOC_SYNC_CTL, &ts) < 0) {
        perror("Failed to start capture");
        return -1;
    }

    if (ioctl(camera_fd, VIDIOC_DQBUF, &fmt) < 0) {
        perror("Failed to dequeue buffer");
        return -1;
    }

    // Save the captured image to the file
    // This is a placeholder, as actual image saving requires additional libraries
    FILE *fp = fopen(filename, "wb");
    if (!fp) {
        perror("Failed to open file for writing");
        return -1;
    }

    fwrite(map, 1, v4l2_get_fmt(camera_fd, &fmt).buf.size, fp);
    fclose(fp);

    if (ioctl(camera_fd, VIDIOC_QBUF, &fmt) < 0) {
        perror("Failed to queue buffer");
        return -1;
    }

    return 0;
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <output_file>\n", argv[0]);
        return EXIT_FAILURE;
    }

    strcpy(filename, argv[1]);

    if (open_camera() < 0) {
        return EXIT_FAILURE;
    }

    while (1) {
        if (capture_image(filename) < 0) {
            break;
        }

        usleep(CAPTURE_INTERVAL_SEC * 1000000 - getpid() * 100000);
    }

    close_camera();
    return EXIT_SUCCESS;
}

