#include <gpiod_bcm2708.h>

#define GPIO_OUTPUTS (17 | 22 | 27)

static int
output_state(const char *gpio, int state)
{
    int ret;

    if (state) {
        ret = gpiod_bcm2708_export(gpio, "User LED");
        if (ret < 0) {
            fprintf(stderr, "Failed to export %s\n", gpio);
            return ret;
        }
    } else {
        ret = gpiod_bcm2708_unexport(gpio);
        if (ret < 0) {
            fprintf(stderr, "Failed to unexport %s\n", gpio);
            return ret;
        }
    }

    return 0;
}

int
main(int argc, char **argv)
{
    struct gpiod_chip *chip;
    struct gpiod_line *lines[3];
    int i;

    if (argc != 2) {
        fprintf(stderr, "Usage: %s <on|off>\n", argv[0]);
        return EXIT_FAILURE;
    }

    for (i = 0; i < 3; ++i) {
        lines[i] = gpiod_bcm2708_get_line(GPIO_OUTPUTS | i);
        if (!lines[i]) {
            fprintf(stderr, "Device not found\n");
            return EXIT_FAILURE;
        }
    }

    chip = gpiod_bcm2708_chip_get();
    if (!chip) {
        fprintf(stderr, "Failed to get chip\n");
        return EXIT_FAILURE;
    }

    for (i = 0; i < 3; ++i) {
        if (strcmp(argv[1], "on") == 0) {
            output_state(lines[i]->name, 1);
            printf("Set %s to ON\n", lines[i]->name);
        } else if (strcmp(argv[1], "off") == 0) {
            output_state(lines[i]->name, 0);
            printf("Set %s to OFF\n", lines[i]->name);
        } else {
            fprintf(stderr, "Invalid argument: %s\n", argv[1]);
            return EXIT_FAILURE;
        }
    }

    while (1) {
        for (i = 0; i < 3; ++i) {
            if (lines[i]->direction == GPIO_OUTPUT) {
                if (lines[i]->value) {
                    printf("%s is ON\n", lines[i]->name);
                } else {
                    printf("%s is OFF\n", lines[i]->name);
                }
            }
        }
        sleep(1);
    }

    for (i = 0; i < 3; ++i) {
        output_state(lines[i]->name, 0);
    }

    gpiod_bcm2708_unexport_all();

    return EXIT_SUCCESS;
}

