        return 1;
    }

    width = WIDTH;
    height = HEIGHT;

    image_buffer = (char *)malloc(width * height * 3 / 2);
    if (!image_buffer) {
        perror("Failed to allocate memory");
        close(cam_fd);
        return 1;
    }

    if (ioctl(cam_fd, VIDIOC_DQBUF, &fmt) < 0) {
        perror("Failed to dequeue buffer");
        free(image_buffer);
        close(cam_fd);
        return 1;
