    ret = read(cam_fd, image_buffer, width * height * 3 / 2);
    if (ret < 0) {
        perror("Failed to read from camera device");
        free(image_buffer);
        close(cam_fd);
        return 1;
    }

    close(cam_fd);

    FILE *fp = fopen("image.bmp", "wb");
    if (!fp) {
        perror("Failed to open output file");
        free(image_buffer);
        return 1;
    }

    fwrite(image_buffer, 1, width * height * 3 / 2, fp);
    fclose(fp);

