    int gpio_pins[4];
    int i;

    // Initialise pigpio library
    if (pigpio_initialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return 1;
    }

    // Set up GPIO pins for PWM output
    for (i = 0; i < 4; i++) {
        gpio_pins[i] = gpio_pins_get(GPIO_PINS[i]);
        if (gpio_pins[i] < 0) {
            fprintf(stderr, "Failed to get GPIO pin %d\n", GPIO_PINS[i]);
            pigpio_terminate();
            return 1;
        }
        pigpio_set_mode(gpio_pins[i], PI_OUTPUT);
    }

    // Start time for cycle duration
    clock_gettime(CLOCK_MONOTONIC, &ts);

    for (int cycle = 1; cycle <= NUM_CYCLES; cycle++) {
        // Set PWM duty cycle (50% in this case)
        pigpio_set_PWM_range(gpio_pins[0], 100);
        pigpio_set_PWM_frequency(gpio_pins[0], 1000);
        pigpio_set_PWM_duty_cycle(gpio_pins[0], 50);

        // Wait for 60 seconds
        while ((clock_gettime(CLOCK_MONOTONIC, &ts) - ts).tv_sec * 1000 + (clock_gettime(CLOCK_MONOTONIC, &ts).tv_nsec / 1000000) < CYCLE_DURATION) {
            // Sleep for remaining time
            struct timespec rem_time;
            rem_time.tv_sec  = CYCLE_DURATION / 1000 - rem_time.tv_sec;
            rem_time.tv_nsec = CYCLE_DURATION * 1000000000L - rem_time.tv_nsec;
            nanosleep(&rem_time, NULL);
        }

        // Report the state
        printf("Cycle %d completed.\n", cycle);
    }

