#define GPIO_OUTPUTS ( "17,22,23,27" )
#define OUTPUT_COUNT ( 4 )

static int g_exit_requested = 0;

static int
output_callback(struct gpiod_chip *chip, struct gpiod_line *line, uint gpiod_line_flags)
{
    int gpio;
    int i;

    gpio = strtoul(line->user_data, NULL, 0);
    printf("GPIO%d: %s\n", gpio / 10 * 10 + (gpio % 10 != 0), gpiod_line_is_high(line) ? "HIGH" : "LOW");

    for (i = 0; i < OUTPUT_COUNT; i++) {
        if (gpio == (17 + i * 10)) {
            break;
        }
    }

    if (i == OUTPUT_COUNT) {
        fprintf(stderr, "Invalid GPIO number: %d\n", gpio);
        return -EINVAL;
    }

    return 0;
}

int
main(int argc, char **argv)
{
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    if (argc != 2) {
        fprintf(stderr, "Usage: %s <output>\n", argv[0]);
        return EXIT_FAILURE;
    }

    ret = gpiod_new(&chip);
    if (ret) {
        fprintf(stderr, "Failed to initialize libgpiod: %s\n", gpiod_strerror(ret));
        return EXIT_FAILURE;
    }

    ret = gpiod_chip_open(chip, argv[1]);
    if (ret) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", gpiod_strerror(ret));
        gpiod_free(chip);
        return EXIT_FAILURE;
    }

    for (int i = 0; i < OUTPUT_COUNT; i++) {
        char gpio_str[10];
        snprintf(gpio_str, sizeof(gpio_str), "%d", 17 + i * 10);
        ret = gpiod_chip_find_line(chip, gpio_str, gpiod_line_request_output, &line);
        if (ret) {
            fprintf(stderr, "Failed to find line for GPIO%s: %s\n", gpio_str, gpiod_strerror(ret));
            gpiod_chip_close(chip);
            gpiod_free(chip);
            return EXIT_FAILURE;
        }

        ret = gpiod_line_export(line);
        if (ret) {
            fprintf(stderr, "Failed to export line for GPIO%s: %s\n", gpio_str, gpiod_strerror(ret));
            gpiod_line_free(line);
            gpiod_chip_close(chip);
            gpiod_free(chip);
            return EXIT_FAILURE;
        }

        ret = gpiod_line_set_owner(line, __FILE__, __LINE__);
        if (ret) {
            fprintf(stderr, "Failed to set line owner for GPIO%s: %s\n", gpio_str, gpiod_strerror(ret));
            gpiod_line_free(line);
            gpiod_chip_close(chip);
            gpiod_free(chip);
            return EXIT_FAILURE;
        }

        ret = gpiod_line_set_direction(line, gpiod_line_output);
        if (ret) {
            fprintf(stderr, "Failed to set line direction for GPIO%s: %s\n", gpio_str, gpiod_strerror(ret));
            gpiod_line_free(line);
            gpiod_chip_close(chip);
            gpiod_free(chip);
            return EXIT_FAILURE;
        }

        ret = gpiod_line_set_value(line, 1);
        if (ret) {
            fprintf(stderr, "Failed to set initial value for GPIO%s: %s\n", gpio_str, gpiod_strerror(ret));
            gpiod_line_free(line);
            gpiod_chip_close(chip);
            gpiod_free(chip);
            return EXIT_FAILURE;
        }

        ret = gpiod_line_set_callback(line, output_callback, "17,22,23,27");
        if (ret) {
            fprintf(stderr, "Failed to set callback for GPIO%s: %s\n", gpio_str, gpiod_strerror(ret));
            gpiod_line_free(line);
            gpiod_chip_close(chip);
            gpiod_free(chip);
            return EXIT_FAILURE;
        }
    }

    while (!g_exit_requested) {
        sleep(0.1);
    }

    for (int i = 0; i < OUTPUT_COUNT; i++) {
        char gpio_str[10];
        snprintf(gpio_str, sizeof(gpio_str), "%d", 17 + i * 10);
        ret = gpiod_line_set_value(gpiod_chip_find_line(chip, gpio_str), 0);
        if (ret) {
            fprintf(stderr, "Failed to set final value for GPIO%s: %s\n", gpio_str, gpiod_strerror(ret));
        }
        gpiod_line_free(gpiod_chip_find_line(chip, gpio_str));
    }

    gpiod_chip_close(chip);
    gpiod_free(chip);

    return EXIT_SUCCESS;
}

