#define OUTPUT_GPIO 27

static int setup_gpio(gpiod_chip *chip, uint line)
{
    struct gpiod_line_request req;
    int r;

    req.line.gpio = line;
    req.flags = 0;
    req.devmask = 0;

    if ((r = gpiod_line_request_add(&req, "my_program")) < 0) {
        fprintf(stderr, "Failed to add line request: %d\n", r);
        return r;
    }

    struct gpiod_chip_request chip_req;
    chip_req.line = &req.line;
    chip_req.flags = 0;

    if ((r = gpiod_chip_request_add(chip, &chip_req)) < 0) {
        fprintf(stderr, "Failed to add chip request: %d\n", r);
        gpiod_line_request_free(req.line);
        return r;
    }

    return 0;
}

static void cleanup_gpio(gpiod_chip *chip, uint line)
{
    struct gpiod_line_request *req = gpiod_line_get(line);
    gpiod_chip_request_free(req->chip, req);
    gpiod_line_request_free(req);
}

