        gpiod_close(fd);
        return 1;
    }

    line = gpiod_chip_get_line(chip, OUTPUT_GPIO);
    if (!line) {
        fprintf(stderr, "Failed to get line for GPIO27\n");
        gpiod_chip_close(chip);
        gpiod_close(fd);
        return 1;
    }

    if (setup_gpio(chip, line)) {
