static int setup_gpio(int gpio) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    chip = gpiod_chip_open_r(NULL);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return -1;
    }

    line = gpiod_chip_get_line(chip, gpio);
    if (!line) {
        fprintf(stderr, "Failed to get line for GPIO %d\n", gpio);
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_export(line);
    if (ret < 0) {
        fprintf(stderr, "Failed to export GPIO %d\n", gpio);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

int main(int argc, char *argv[]) {
    struct gpiod_chip *chip;
    struct gpiod_line *line_out, *line_in;
    int ret;

    if (argc != 2) {
        fprintf(stderr, "Usage: %s <output_state>\n", argv[0]);
        return 1;
    }

    ret = setup_gpio(GPIO_OUTPUT);
    if (ret < 0) {
        return ret;
    }

    line_out = gpiod_line_in_export(gpiod_chip_open_r(NULL), GPIO_OUTPUT);
    if (!line_out) {
        fprintf(stderr, "Failed to get line for GPIO %d output\n", GPIO_OUTPUT);
        gpiod_line_release(line_out);
        return 1;
    }

    ret = gpiod_line_request_set_value(line_out, (argv[1][0] == '1'));
    if (ret < 0) {
        fprintf(stderr, "Failed to set output state for GPIO %d\n", GPIO_OUTPUT);
        gpiod_line_release(line_out);
        return 1;
    }

    ret = setup_gpio(GPIO_INPUT);
    if (ret < 0) {
        return ret;
    }

    line_in = gpiod_line_in_export(gpiod_chip_open_r(NULL), GPIO_INPUT);
    if (!line_in) {
        fprintf(stderr, "Failed to get line for GPIO %d input\n", GPIO_INPUT);
        gpiod_line_release(line_in);
        return 1;
    }

    while (1) {
