#define DEVICE "/dev/spidev0.0"

int main(int argc, char *argv[]) {
    int fd;
    char msg[256];
    int ret;
    unsigned int data;

    if (argc != 2) {
        fprintf(stderr, "Usage: %s <device>\n", argv[0]);
        return 1;
    }

    if (strcmp(argv[1], DEVICE) != 0) {
        fprintf(stderr, "Error: Device must be %s\n", DEVICE);
        return 1;
    }

    fd = open(DEVICE, O_RDWR);
    if (fd < 0) {
        perror("Failed to open SPI device");
        return 1;
    }

    if (gpioInitialise() < 0) {
        perror("Failed to initialize GPIO");
        close(fd);
        return 1;
    }

    while (1) {
        ret = ioctl(fd, SPI_RDFAST, &data);
        if (ret < 0) {
            perror("Failed to read from SPI device");
            break;
        }

        if (data & 0x80000000) {
            printf("Temperature: %d°C\n", (int)((data & 0x7FFFFFFF) / 10.0));
        } else {
            printf("Channel %d: %d°C\n", (data >> 24) & 0x03, (int)((data & 0xFFFFFF) / 10.0));
        }
    }

    close(fd);
    gpioTerminate();

    return 0;
}

#include <stdio.h>
