#include <gpiod.h>

#define GPIO_17 17
#define GPIO_18 18

static int line_state[2] = {0};
static struct gpiod_chip *chip;

static int
gpio_callback(struct gpiod_chip *chip, struct gpiod_line *line, uint gpiod_line_flags)
{
    line_state[line->line] = gpiod_is_high(line);
    printf("State of GPIO%d: %s\n", line->line, line_state[line->line] ? "HIGH" : "LOW");
    return 0;
}

int
main(int argc, char **argv)
{
    int ret;

    ret = gpiod_init();
    if (ret < 0) {
        fprintf(stderr, "Failed to initialize libgpiod\n");
        return ret;
    }

    chip = gpiod_chip_open(GPIO_17, "user");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO%d\n", GPIO_17);
        gpiod_exit();
        return -1;
    }

    chip = gpiod_chip_open(GPIO_18, "user");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO%d\n", GPIO_18);
        gpiod_chip_close(chip);
        gpiod_exit();
        return -1;
    }

    struct gpiod_line_request req[2] = {0};
    req[0].line.type = GPIO_LINE_OUTPUT;
    req[0].line.pin = GPIO_17;
    req[0].line.debounce = 0;
    req[0].line.flags = 0;
    req[0].enable_on_mask = 1 << GPIO_17;
    req[0].enable_on_value = 1;
    req[0].line.name = "GPIO17";

    req[1].line.type = GPIO_LINE_OUTPUT;
    req[1].line.pin = GPIO_18;
    req[1].line.debounce = 0;
    req[1].line.flags = 0;
    req[1].enable_on_mask = 1 << GPIO_18;
    req[1].enable_on_value = 1;
    req[1].line.name = "GPIO18";

    for (int i = 0; i < 2; i++) {
        ret = gpiod_add_line_request(chip, &req[i], i == 0 ? 1 : 0);
        if (ret < 0) {
            fprintf(stderr, "Failed to add line request for GPIO%d\n", i == 0 ? GPIO_17 : GPIO_18);
            gpiod_chip_close(chip);
            gpiod_exit();
            return ret;
        }
    }

    gpiod_line_request_set_callback(req[0].line.line, &gpio_callback);
    gpiod_line_request_set_callback(req[1].line.line, &gpio_callback);

    while (1) {
        usleep(100000); // Sleep for 0.1 seconds
        for (int i = 0; i < 2; i++) {
            if (line_state[i]) {
                gpiod_line_export(req[i].line.line, 0);
            } else {
                gpiod_line_export(req[i].line.line, 1);
            }
        }
    }

    for (int i = 0; i < 2; i++) {
        gpiod_line_request_free(req[i]);
    }
    gpiod_chip_close(chip);
    gpiod_exit();

    return 0;
}

#include <stdio.h>
