#define TR_PIN 4
#define ECHO_PIN 17
#define TLC_PIN 18
#define GPIO_TRIGGER 27

int main(int argc, char *argv[]) {
    struct gpiod_chip *chip;
    struct gpiod_line *tr_line;
    struct gpiod_line *echo_line;
    struct gpiod_line *tlc_line;
    int ret;

    chip = gpiod_chip_open("/dev/gpiod", O_RDWR);
    if (!chip) {
        fprintf(stderr, "Failed to open gpiod chip\n");
        return 1;
    }

    tr_line = gpiod_chip_get_line(chip, "GPIO%d", GPIO_TRIGGER);
    if (!tr_line) {
        fprintf(stderr, "Failed to get trigger line\n");
        gpiod_chip_close(chip);
        return 1;
    }

    echo_line = gpiod_chip_get_line(chip, "GPIO%d", ECHO_PIN);
    if (!echo_line) {
        fprintf(stderr, "Failed to get echo line\n");
        gpiod_chip_close(chip);
        return 1;
    }

    tlc_line = gpiod_chip_get_line(chip, "GPIO%d", TLC_PIN);
    if (!tlc_line) {
        fprintf(stderr, "Failed to get TLC line\n");
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_export(tr_line, "Trigger") || gpiod_line_export(echo_line, "Echo") || gpiod_line_export(tlc_line, "TLC")) {
        fprintf(stderr, "Failed to export lines\n");
        gpiod_chip_close(chip);
        return 1;
    }

    gpiod_line_set_direction(tr_line, GPIO_OUTPUT);
    gpiod_line_set_direction(echo_line, GPIO_INPUT);
    gpiod_line_set_direction(tlc_line, GPIO_OUTPUT);

    // Send trigger pulse
    ret = gpiod_line_write(tr_line, 1);
    if (ret) {
        fprintf(stderr, "Failed to write to trigger line\n");
        gpiod_line_unref(tr_line);
        gpiod_line_unref(echo_line);
        gpiod_line_unref(tlc_line);
        gpiod_chip_close(chip);
        return 1;
    }
    usleep(10);
    ret = gpiod_line_write(tr_line, 0);
    if (ret) {
        fprintf(stderr, "Failed to write to trigger line\n");
        gpiod_line_unref(tr_line);
        gpiod_line_unref(echo_line);
        gpiod_line_unref(tlc_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Measure pulse width
    ret = gpiod_line_read(echo_line, &echo_state);
    if (ret) {
        fprintf(stderr, "Failed to read from echo line\n");
        gpiod_line_unref(tr_line);
        gpiod_line_unref(echo_line);
        gpiod_line_unref(tlc_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Calculate distance
    int duration = echo_state.value.u64;
    int distance = duration * 0.034 / 2;

    printf("Distance: %.2f cm\n", distance);

    gpiod_line_unref(tr_line);
    gpiod_line_unref(echo_line);
    gpiod_line_unref(tlc_line);
    gpiod_chip_close(chip);

    return 0;
}

