#define DEVICE "/dev/ttyAMA0"
#define BAUD 9600
#define READ_SIZE 10

static volatile sig_atomic_t sigint_received = 0;

static void sigint_handler(int signum)
{
    sigint_received = 1;
}

static int setup_serial(int fd)
{
    struct termios term;
    memset(&term, 0, sizeof(term));
    term.c_cflag = BAUD | CS8 | CLOCAL | CREAD;
    tcgetattr(fd, &term);
    tcflush(fd, TCIFLUSH);
    tcsetattr(fd, TCSANOW, &term);
    return 0;
}

int main(int argc, char *argv[])
{
    int fd = open(DEVICE, O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd == -1) {
        if (errno != ENXIO) {
            fprintf(stderr, "Error opening %s: %s\n", DEVICE, strerror(errno));
            return 1;
        }
        fprintf(stderr, "Device %s not present\n", DEVICE);
        return 1;
    }

    if (setup_serial(fd) != 0) {
        close(fd);
        fprintf(stderr, "Error setting up serial port\n");
        return 1;
    }

    signal(SIGINT, sigint_handler);

    while (!sigint_received) {
        char buffer[READ_SIZE];
        ssize_t bytes_read = read(fd, buffer, sizeof(buffer));
        if (bytes_read == -1 && errno != EAGAIN) {
            fprintf(stderr, "Error reading from %s: %s\n", DEVICE, strerror(errno));
            close(fd);
            return 1;
        }
        if (bytes_read > 0) {
            buffer[bytes_read] = '\0';
            write(STDOUT_FILENO, buffer, bytes_read);
            printf("\n");
        }
        usleep(10000);
    }

    close(fd);
    return 0;
}

