        gpiod_chip_close(chip);
        gpiod_free(ctx);
        return 1;
    }

    if (gpiod_line_export(line_trig, "gpio17") < 0 || gpiod_line_export(line_echo, "gpio18") < 0) {
        fprintf(stderr, "Failed to export GPIO17 or GPIO18\n");
        gpiod_line_unref(line_trig);
