#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <gpiod.h>

#define TCS34725_ADDR 0x29
#define REG_CHOOSE_COLOR 0x00
#define REG_READ_COLOR_MSB 0x01
#define REG_READ_COLOR_LSB 0x02

int i2c_fd;
int setup_i2c() {
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open i2c bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, TCS34725_ADDR) < 0) {
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    return 0;
}

void cleanup_i2c() {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
}

uint16_t read_color_register(int reg_addr) {
    uint8_t msb, lsb;

    if (write(i2c_fd, &reg_addr, 1) != 1) {
        perror("Failed to write to I2C");
        return -1;
    }

    if (read(i2c_fd, &msb, 1) != 1) {
        perror("Failed to read from I2C");
        return -1;
    }

    if (read(i2c_fd, &lsb, 1) != 1) {
        perror("Failed to read from I2C");
        return -1;
    }

    return (msb << 8) | lsb;
}

int main() {
    int ret;
    struct gpiod_chip chip;
    gpiod_chip_init(&chip, "gpio");

    ret = setup_i2c();
    if (ret < 0) {
        fprintf(stderr, "Error setting up I2C\n");
        return ret;
    }

    while (1) {
        uint16_t color = read_color_register(REG_READ_COLOR_MSB);
        if (color != -1) {
            printf("Color: %u\n", color);
        } else {
            fprintf(stderr, "Error reading color register\n");
            cleanup_i2c();
            return 1;
        }
        usleep(500000); // Sleep for 0.5 seconds
    }

    cleanup_i2c();
    gpiod_chip_put(chip);
    return 0;
}

