static int serial_fd = -1;
static struct termios termios;

static void serial_init() {
    serial_fd = open(SERIAL_DEVICE, O_RDWR | O_NOCTTY | O_NDELAY);
    if (serial_fd == -1) {
        fprintf(stderr, "Error opening serial port: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    tcgetattr(serial_fd, &termios);
    cfsetispeed(&termios, BAUD_RATE);
    cfsetospeed(&termios, BAUD_RATE);

    termios.c_cflag |= (CLOCAL | CREAD);
    termios.c_cflag &= ~PARENB;
    termios.c_cflag &= ~CSTOPB;
    termios.c_cflag &= ~CSIZE;
    termios.c_cflag |= CS8;

    tcflush(serial_fd, TCIFLUSH);
    tcsetattr(serial_fd, TCSANOW, &termios);
}

static void serial_read() {
    static char buffer[256];
    int bytes_read = read(serial_fd, buffer, sizeof(buffer));
    if (bytes_read > 0) {
        buffer[bytes_read] = '\0';
        printf("Received: %s\n", buffer);
    }
}

static void signal_handler(int signum) {
    if (signum == SIGINT) {
        printf("\nExiting...\n");
        close(serial_fd);
        exit(EXIT_SUCCESS);
    }
}

