        return ret;
    }

    ret = gpiod_chip_get_line(chip, gpio, 0, &line);
    if (ret < 0) {
        gpiod_chip_close(chip);
        return ret;
    }

    ret = gpiod_line_export(line, NULL);
    if (ret < 0) {
        gpiod_line_unref(line);
        gpiod_chip_close(chip);
        return ret;
    }

    return 0;
}

static void cleanup_gpio(struct gpiod_line *line) {
    gpiod_line_unref(line);
    gpiod_chip_close(line->chip);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *lines[3];
    int ret;
    unsigned int delay_ms = 10000; // 0.1s

    if (gpiod_init() < 0) {
        fprintf(stderr, "Failed to initialize libgpiod\n");
        return 1;
    }

    for (int i = 0; i < 3; i++) {
        lines[i] = NULL;
    }

    for (int i = 0; i < 3; i++) {
        ret = setup_gpio(i == 0 ? GPIO_OUTPUT : (i == 1 ? GPIO_INPUT1 : GPIO_INPUT2));
        if (ret < 0) {
            fprintf(stderr, "Failed to set up GPIO %d\n", i == 0 ? GPIO_OUTPUT : (i == 1 ? GPIO_INPUT1 : GPIO_INPUT2));
            cleanup_gpio(lines[i - 1]);
            return ret;
        }
        lines[i] = gpiod_line_get(lines[i - 1]->chip, lines[i - 1]->id);
    }

    while (1) {
        for (int i = 0; i < 3; i++) {
            if (i == 0) {
                gpiod_line_direction_set(lines[i], GPIO_OUTPUT);
                gpiod_line_value_set(lines[i], 1);
            } else {
                gpiod_line_direction_set(lines[i], GPIO_INPUT);
                gpiod_line_value_get(lines[i]);
            }
        }

        printf("State: %d, %d, %d\n", i == 0 ? 1 : (i == 1 ? gpiod_line_value_get(lines[i]) : 0), i == 1 ? gpiod_line_value_get(lines[i]) : 0, i == 2 ? gpiod_line_value_get(lines[i]) : 0);

        usleep(delay_ms);
    }

    for (int i = 0; i < 3; i++) {
        cleanup_gpio(lines[i]);
    }

    gpiod_uninit();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <gpiozero.h>

#define MPU6050_ADDR 0x68
#define MPU6050_REG_ACCEL_XOUT_H (0x3B)
#include <wiringPiI2C.h>

// Function to read data from MPU6050
int read_mpu6050_accel(int16_t *x, int16_t *y, int16_t *z) {
    if (wiringPiI2C_rdwr(MPU6050_ADDR, 2, (void *)&MPU6050_REG_ACCEL_XOUT_H, 2, (void *)x) != 2) {
        perror("Error reading from MPU6050");
        return -1;
    }

    if (wiringPiI2C_rdwr(MPU6050_ADDR, 2, (void *)&MPU6050_REG_ACCEL_YOUT_H, 2, (void *)y) != 2) {
        perror("Error reading from MPU6050");
        return -1;
    }

    if (wiringPiI2C_rdwr(MPU6050_ADDR, 2, (void *)&MPU6050_REG_ACCEL_ZOUT_H, 2, (void *)z) != 2) {
        perror("Error reading from MPU6050");
        return -1;
    }

    return 0;
}

int main() {
    int fd;
    int16_t ax, ay, az;
    struct i2c_rdwr_ioctl_data rdwr_data;

    if ((fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Failed to open the i2c bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        return -1;
    }

    rdwr_data.u8buf = (uint8_t *) &ax;
    rdwr_data.u8buf_len = sizeof(ax);
    rdwr_data.u8buf_len_exp = sizeof(ax);
    rdwr_data.u8buf2 = (uint8_t *) &ay;
    rdwr_data.u8buf2_len = sizeof(ay);
    rdwr_data.u8buf2_len_exp = sizeof(ay);
    rdwr_data.u8buf3 = (uint8_t *) &az;
    rdwr_data.u8buf3_len = sizeof(az);
    rdwr_data.u8buf3_len_exp = sizeof(az);

    if (ioctl(fd, I2C_RDWR, &rdwr_data) < 0) {
        perror("Error during i2c transfer");
        return -1;
    }

    while (1) {
        printf("Acceleration (m/s^2): (%d, %d, %d)\n", ax / 16384.0, ay / 655.36, az / 16384.0);
        sleep(1);
    }

    close(fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <gpiod.h>

#define OUTPUT_GPIO 17
#define INTERVAL_SEC 0.6

static int setup_gpio(gpiod_chip *chip, const char *label)
{
    struct gpiod_line line_info;
    int ret;

    ret = gpiod_chip_get_line(chip, label, &line_info);
    if (ret) {
        fprintf(stderr, "Failed to get line %s, error %d\n", label, ret);
        return ret;
    }

    if (line_info.flags & GPIOD_LINE_OUTPUT) {
        struct gpiod_gpiooutput output;
        gpiod_gpio_direction_output(line_info.id, &output);
        return 0;
    } else {
        fprintf(stderr, "Line %s is not an output\n", label);
        return -EINVAL;
    }
}

int main(int argc, char *argv[])
{
    struct gpiod_chip *chip;
    int ret;

    ret = gpiod_chip_open(&chip, "GPIO17");
    if (ret) {
        fprintf(stderr, "Failed to open GPIO chip, error %d\n", ret);
        return ret;
    }

    ret = setup_gpio(chip, "GPIO17");
    if (ret) {
        gpiod_chip_close(chip);
        return ret;
    }

    while (1) {
        gpiod_gpio_direction_output(OUTPUT_GPIO, 1);
        usleep(INTERVAL_SEC * 1e6);
        gpiod_gpio_direction_output(OUTPUT_GPIO, 0);
        usleep(INTERVAL_SEC * 1e6);

        printf("Toggled GPIO %d\n", OUTPUT_GPIO);
        sleep(INTERVAL_SEC);
    }

    gpiod_chip_close(chip);
    return 0;
}
